        return [index + 1, row['Item Name'], row['Batch No'] || "DEFAULT", row['Expiry'] ? moment(row['Expiry']).format("MM/YY") : "-", Number(row['MRP']).toFixed(2), row['Qty'], Number(row['Price']).toFixed(2), gross.toFixed(2), sch.toFixed(2), discPct + "%", discAmt.toFixed(2), Number(row['Taxable']).toFixed(2), Number(row['Tax %']) + "%", Number(row['GST $']).toFixed(2), Number(row['Net $']).toFixed(2)];
      }),
      didDrawPage: data => {
        const totalPages = doc.internal.getNumberOfPages();
        drawMainHeader(data.pageNumber, totalPages);
      },
      theme: 'grid',
      styles: {
        fontSize: 7.5,
        cellPadding: 2,
        lineColor: [0, 0, 0],
        lineWidth: 0.5,
        textColor: [0, 0, 0]
      },
      headStyles: {
        fillColor: [255, 255, 255],
        textColor: [0, 0, 0],
        fontStyle: 'bold',
        lineWidth: 0.5
      },
      columnStyles: {
        0: {
          cellWidth: 20
        },
        1: {
          cellWidth: 'auto',
          minCellWidth: 100
        }
      }
    });
    doc.autoTable({
      startY: doc.lastAutoTable.finalY + 8,
      margin: {
        left: margin
      },
      head: [["TAX SUMMARY", "PCS", "GROSS", "SCH", "DISC", "TAXABLE", "TAX", "NET"]],
      body: summaryData.map(row => [row.PARTICULARS, row.Pcs, row.Gross.toFixed(2), row.Sch.toFixed(2), row.Disc.toFixed(2), row.Taxable.toFixed(2), row.Tax.toFixed(2), row.Net.toFixed(2)]),
      theme: 'grid',
      styles: {
        fontSize: 8,
        cellPadding: 2.5,
        lineColor: [0, 0, 0],
        lineWidth: 0.5,
        textColor: [0, 0, 0]
      },
      headStyles: {
        fillColor: [255, 255, 255],
        textColor: [0, 0, 0],
        fontStyle: 'bold',
        lineWidth: 0.5
      },
      bodyStyles: row => row.at(0) === 'Grand Total' ? {
        fontStyle: 'bold',
        fillColor: [250, 250, 250]
      } : {}
    });
    const wordsY = doc.lastAutoTable.finalY + 20;
    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.text("Total Amount (in words):", margin, wordsY);
    doc.setFont("helvetica", "normal");
    doc.text(toWords(Math.round(grandTotal)), margin + 150, wordsY);
    const notesY = wordsY + 20;
    doc.setFontSize(8.5);
    doc.setFont("helvetica", "bold");
    doc.text("Notes / Terms:", margin, notesY);
    doc.setFont("helvetica", "normal");
    doc.text("1. Payments will be made as per the GRN accepted amount.", margin, notesY + 14);
    doc.text("2. This is a computer generated document and does not require a physical signature.", margin, notesY + 26);
    const fileName = (grnHeader.invoice_number || "GRN") + ".pdf";
    download(doc.output('dataurlstring'), fileName, "application/pdf");
    showAlert("GRN Downloaded Successfully", "success");
  } catch (error) {
    showAlert("PDF Layout Error: " + error.message, "error");
  }
}

