actionConfiguration.body:
async dnHeader => {
  try {
    if (!dnHeader || !dnHeader.id) throw new Error("No Debit Note data selected.");
    if (typeof jspdf === "undefined") throw new Error("jspdf library not loaded.");
    const jsPDFConstructor = jspdf.jsPDF || jspdf;
    const doc = new jsPDFConstructor('p', 'pt', 'a4');
    if (typeof doc.autoTable !== "function" && jspdf.plugin && jspdf.plugin.autotable) {
      jsPDFConstructor.API.autoTable = jspdf.plugin.autotable;
    }
    const dnLines = getDebitNoteLines.data || [];
    const summaryData = PDFUtils.getDNTaxSummary(dnLines);
    const grandTotal = Number(dnHeader.amount || 0);
    const brand = Global_Assets.getSummary();
    const margin = 20;
    const pageWidth = doc.internal.pageSize.width;
    const pageHeight = doc.internal.pageSize.height;
    const drawMainHeader = (currentPage, totalPages) => {
      const headerY = margin;
      try {
        const logo = Global_Assets.getLogo();
        if (logo && logo.startsWith("data:image/")) {
          doc.addImage(logo, 'PNG', margin, headerY, 90, 30);
        }
      } catch (e) {
        console.error("Logo error", e);
      }
      doc.setTextColor(0, 0, 0);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(16);
      const title = (dnHeader.note_type || "DEBIT NOTE").toUpperCase();
      doc.text(title, pageWidth / 2, headerY + 15, {
        align: "center"
      });
      doc.setFontSize(11);
      doc.setFont("helvetica", "normal");
      doc.text(String(dnHeader.debit_note_number), pageWidth / 2, headerY + 30, {
        align: "center"
      });
      const boxesY = headerY + 45;
      const gap = 8;
      const boxWidth = (pageWidth - margin * 2 - gap * 2) / 3;
      const boxHeight = 90;
      PDFUtils._drawSimpleBox(doc, margin, boxesY, boxWidth, boxHeight, [["DN NUMBER", String(dnHeader.debit_note_number)], ["DATE", moment(dnHeader.debit_note_date).format("DD/MM/YYYY")], ["LINKED INV", String(dnHeader.linked_invoice_number || "-")], ["TOTAL AMT", "INR " + Number(grandTotal).toFixed(2)], ["PAGE", `${currentPage} / ${totalPages}`]]);
      PDFUtils._drawSimpleBox(doc, margin + boxWidth + gap, boxesY, boxWidth, boxHeight, [["From", String(brand.regt_name)], ["Address", String(brand.address)], ["GST", String(brand.gst)], ["Contact", String(brand.contact_no)], ["Email", String(brand.email)]]);
      const vAddr = [dnHeader.vendor_address, dnHeader.vendor_city, dnHeader.vendor_pin].filter(Boolean).join(", ");
      PDFUtils._drawSimpleBox(doc, margin + boxWidth * 2 + gap * 2, boxesY, boxWidth, boxHeight, [["Vendor", String(dnHeader.vendor_name)], ["Address", vAddr || "-"], ["GST", String(dnHeader.vendor_gst || "-")], ["Contact", String(dnHeader.vendor_contact || "-")], ["Place of Supply", String(dnHeader.place_of_supply || "-")]]);
      return boxesY + boxHeight + 15;
    };
    doc.autoTable({
      startY: 160,
      margin: {
        left: margin,
        right: margin,
        top: 160,
        bottom: 120
      },
      head: [["S.N", "ITEM NAME", "CODE / EAN", "HSN", "BATCH / EXP", "MRP", "QTY", "PRICE", "TXBL", "GST%", "GST$", "NET$"]],
      body: dnLines.map((row, index) => {
        const expiryStr = row['Expiry'] ? moment(row['Expiry']).format("MM/YY") : "-";
        return [index + 1, row['Item Name'], `${row['product_code'] || ""}\n${row['EAN Code'] || ""}`, row['hsn_code'] || "-", `${row['Batch No'] || ""}\n${expiryStr}`, Number(row['MRP'] || 0).toFixed(2), row['Qty'], Number(row['Price'] || 0).toFixed(2), Number(row['Taxable $'] || 0).toFixed(2), row['GST %'] + "%", Number(row['GST $'] || 0).toFixed(2), Number(row['Net $'] || 0).toFixed(2)];
      }),
      didDrawPage: data => {
        drawMainHeader(data.pageNumber, doc.internal.getNumberOfPages());
      },
      theme: 'grid',
      styles: {
        fontSize: 7,
        cellPadding: 3,
        lineColor: [100, 100, 100],
        lineWidth: 0.5,
        textColor: [0, 0, 0]
      },
      headStyles: {
        fillColor: [240, 240, 240],
        textColor: [0, 0, 0],
        fontStyle: 'bold'
      },
      columnStyles: {
        0: {
          cellWidth: 20
        },
        1: {
          cellWidth: 'auto',
          minCellWidth: 100
        },
        2: {
          cellWidth: 55
        },
        4: {
          cellWidth: 55
        },
        5: {
          halign: 'right'
        },
        6: {
          halign: 'center'
        },
        7: {
          halign: 'right'
        },
        8: {
          halign: 'right'
        },
        9: {
          halign: 'center'
        },
        10: {
          halign: 'right'
        },
        11: {
          halign: 'right'
        }
      }
    });
    let currentY = doc.lastAutoTable.finalY + 15;
    if (currentY > pageHeight - 220) {
      doc.addPage();
      currentY = 160;
    }
    doc.autoTable({
      startY: currentY,
      margin: {
        left: margin
      },
      head: [["TAX SUMMARY", "TOTAL PCS", "TAXABLE VALUE", "TAX AMOUNT", "NET AMOUNT"]],
      body: summaryData.map(row => [row.PARTICULARS, row.Pcs, row.Taxable.toFixed(2), row.Tax.toFixed(2), row.Net.toFixed(2)]),
      didDrawPage: data => {
        drawMainHeader(data.pageNumber, doc.internal.getNumberOfPages());
      },
      theme: 'grid',
      styles: {
        fontSize: 8,
        cellPadding: 4,
        lineColor: [0, 0, 0],
        lineWidth: 0.5,
        textColor: [0, 0, 0]
      },
      headStyles: {
        fillColor: [245, 245, 245],
