async function () {
  try {
    if (typeof jspdf === "undefined") throw new Error("jsPDF library not loaded. Add it in App Settings → External Libraries.");
    const jsPDFConstructor = jspdf.jsPDF || jspdf;
    const doc = new jsPDFConstructor("p", "pt", "a4");
    const raw = Brand_History.data;
    if (!raw || !raw.brand) throw new Error("Brand_History.data is empty or missing.");
    const brand = raw.brand;
    const sv = raw.stock_valuation || ({});
    const summary = raw.summary || ({});
    const gross = summary.gross || ({});
    const net = summary.net || ({});
    const margins = summary.margins || ({});
    const monthly = (raw.monthly_trends || []).filter(m => m.sales > 0 || m.purchase > 0);
    const txs = raw.transactions || [];
    const PW = doc.internal.pageSize.width;
    const PH = doc.internal.pageSize.height;
    const ML = 28;
    const MR = 28;
    const CW = PW - ML - MR;
    const HEADER_H = 115;
    const C = {
      black: [0, 0, 0],
      white: [255, 255, 255],
      darkBg: [20, 30, 48],
      accentGreen: [22, 163, 74],
      accentBlue: [37, 99, 235],
      accentAmber: [217, 119, 6],
      accentRed: [220, 38, 38],
      lightGray: [245, 247, 250],
      midGray: [100, 116, 139],
      borderGray: [203, 213, 225],
      kpiGreen: [220, 252, 231],
      kpiBlue: [219, 234, 254],
      kpiAmber: [254, 243, 199],
      kpiRed: [254, 226, 226],
      kpiGray: [241, 245, 249]
    };
    const setFont = (style, size, color) => {
      doc.setFont("helvetica", style);
      doc.setFontSize(size);
      if (color) doc.setTextColor(...color);
    };
    const setFill = rgb => doc.setFillColor(...rgb);
    const setDraw = rgb => doc.setDrawColor(...rgb);
    const fmt = v => "Rs." + Number(v).toLocaleString("en-IN", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
    const fmtN = v => Number(v).toLocaleString("en-IN");
    const pct = v => String(v);
    const drawPageHeader = (pageNum, totalPages) => {
      setFill(C.darkBg);
      doc.rect(0, 0, PW, 52, "F");
      setFont("bold", 20, C.white);
      doc.text(brand.name.toUpperCase() + " — BRAND HISTORY REPORT", ML, 33);
      setFill([37, 99, 235]);
      doc.roundedRect(PW - MR - 60, 12, 55, 22, 4, 4, "F");
      setFont("bold", 10, C.white);
      doc.text(brand.code.trim(), PW - MR - 32, 27, {
        align: "center"
      });
      setFill([30, 41, 59]);
      doc.rect(0, 52, PW, 22, "F");
      setFont("normal", 8, [148, 163, 184]);
      doc.text("Generated: " + new Date().toLocaleDateString("en-IN", {
        day: "2-digit",
        month: "short",
        year: "numeric"
      }), ML, 66);
      doc.text("Status: " + (brand.is_active ? "ACTIVE" : "INACTIVE"), ML + 140, 66);
      doc.text(`Page ${pageNum} of ${totalPages}`, PW - MR, 66, {
        align: "right"
      });
      return 82;
    };
    let Y = drawPageHeader(1, 1);
    const drawSectionLabel = (y, label) => {
      setFont("bold", 9, C.midGray);
      doc.text(label.toUpperCase(), ML, y);
      setDraw(C.borderGray);
      doc.setLineWidth(0.5);
      doc.line(ML + doc.getTextWidth(label.toUpperCase()) + 6, y - 3, PW - MR, y - 3);
      return y + 10;
    };
    Y = drawSectionLabel(Y + 8, "Key Performance Indicators");
    const kpis = [{
      label: "Net Sales",
      val: fmt(net.sales?.amount || 0),
      sub: fmtN(net.sales?.qty || 0) + " units",
      bg: C.kpiGreen,
      accent: C.accentGreen
    }, {
      label: "Net Purchases",
      val: fmt(net.purchases?.amount || 0),
      sub: fmtN(net.purchases?.qty || 0) + " units",
      bg: C.kpiBlue,
      accent: C.accentBlue
    }, {
      label: "Gross Margin",
      val: pct(margins.gross_margin_pct || "0%"),
      sub: "Net: " + pct(margins.net_realized_margin_pct || "0%"),
      bg: C.kpiAmber,
      accent: C.accentAmber
    }, {
      label: "Sales Returns",
      val: fmt(gross.sales_returns?.amount || 0),
      sub: fmtN(gross.sales_returns?.qty || 0) + " units",
      bg: C.kpiRed,
      accent: C.accentRed
    }, {
      label: "Stock Value",
      val: fmt(sv.valuation || 0),
      sub: fmtN(sv.qty || 0) + " units on hand",
      bg: C.kpiGray,
      accent: C.midGray
    }, {
      label: "Return Rate",
      val: ((gross.sales_returns?.qty || 0) / (gross.sales?.qty || 1) * 100).toFixed(2) + "%",
      sub: "of gross sales qty",
      bg: C.kpiRed,
      accent: C.accentRed
    }];
    const CARD_COLS = 3;
    const CARD_W = (CW - 10 * (CARD_COLS - 1)) / CARD_COLS;
    const CARD_H = 52;
    const CARD_GAP = 10;
    kpis.forEach((k, i) => {
      const col = i % CARD_COLS;
      const row = Math.floor(i / CARD_COLS);
      const cx = ML + col * (CARD_W + CARD_GAP);
      const cy = Y + row * (CARD_H + CARD_GAP);
      setFill(k.bg);
      setDraw(C.borderGray);
      doc.setLineWidth(0.5);
      doc.roundedRect(cx, cy, CARD_W, CARD_H, 5, 5, "FD");
      setFill(k.accent);
      doc.roundedRect(cx, cy, 4, CARD_H, 2, 2, "F");
      setFont("normal", 7.5, C.midGray);
      doc.text(k.label.toUpperCase(), cx + 10, cy + 14);
      setFont("bold", 13, k.accent);
      doc.text(k.val, cx + 10, cy + 32);
      setFont("normal", 7, C.midGray);
      doc.text(k.sub, cx + 10, cy + 45);
    });
    Y = Y + 2 * (CARD_H + CARD_GAP) + 14;
    Y = drawSectionLabel(Y, "Sales & Purchase Summary");
    doc.autoTable({
      startY: Y,
      margin: {
        left: ML,
        right: MR
      },
      head: [["METRIC", "GROSS SALES", "GROSS PURCHASES", "SALES RETURNS", "PURCH. RETURNS", "NET SALES", "NET PURCHASES"]],
      body: [["QUANTITY", fmtN(gross.sales?.qty || 0), fmtN(gross.purchases?.qty || 0), fmtN(gross.sales_returns?.qty || 0), fmtN(gross.purchase_returns?.qty || 0), fmtN(net.sales?.qty || 0), fmtN(net.purchases?.qty || 0)], ["TAXABLE (Rs.)", fmtN((gross.sales?.taxable || 0).toFixed(2)), fmtN((gross.purchases?.taxable || 0).toFixed(2)), fmtN((gross.sales_returns?.taxable || 0).toFixed(2)), "—", fmtN((net.sales?.taxable || 0).toFixed(2)), "—"], ["TAX (Rs.)", fmtN((gross.sales?.tax || 0).toFixed(2)), fmtN((gross.purchases?.tax || 0).toFixed(2)), fmtN((gross.sales_returns?.tax || 0).toFixed(2)), "—", "—", "—"], ["AMOUNT (Rs.)", fmtN((gross.sales?.amount || 0).toFixed(2)), fmtN((gross.purchases?.amount || 0).toFixed(2)), fmtN((gross.sales_returns?.amount || 0).toFixed(2)), fmtN((gross.purchase_returns?.amount || 0).toFixed(2)), fmtN((net.sales?.amount || 0).toFixed(2)), fmtN((net.purchases?.amount || 0).toFixed(2))]],
      theme: "grid",
      styles: {
        fontSize: 7.5,
        cellPadding: 4,
        lineColor: C.borderGray,
        lineWidth: 0.4,
        textColor: C.black,
        valign: "middle"
      },
      headStyles: {
        fillColor: C.darkBg,
        textColor: C.white,
        fontStyle: "bold",
        fontSize: 7,
        halign: "center"
      },
      columnStyles: {
        0: {
          fontStyle: "bold",
          fillColor: C.lightGray,
          cellWidth: 70
        },
        1: {
          halign: "right"
        },
        2: {
          halign: "right"
        },
        3: {
          halign: "right"
        },
        4: {
          halign: "right"
        },
        5: {
          halign: "right",
          fontStyle: "bold"
        },
        6: {
          halign: "right",
          fontStyle: "bold"
        }
      },
      alternateRowStyles: {
        fillColor: C.white
      }
    });
