    const doc = new jsPDFConstructor("p", "pt", "a4");
    const raw = Brand_History.data;
    if (!raw || !raw.brand) throw new Error("Brand_History.data is empty or missing.");
    const brand = raw.brand;
    const sv = raw.stock_valuation || ({});
