    const ML = 28;
    const MR = 28;
    const CW = PW - ML - MR;
    const HEADER_H = 115;
    const C = {
      black: [0, 0, 0],
      white: [255, 255, 255],
      darkBg: [20, 30, 48],
      accentGreen: [22, 163, 74],
      accentBlue: [37, 99, 235],
      accentAmber: [217, 119, 6],
      accentRed: [220, 38, 38],
      lightGray: [245, 247, 250],
      midGray: [100, 116, 139],
      borderGray: [203, 213, 225],
      kpiGreen: [220, 252, 231],
      kpiBlue: [219, 234, 254],
      kpiAmber: [254, 243, 199],
      kpiRed: [254, 226, 226],
      kpiGray: [241, 245, 249]
    };
    const setFont = (style, size, color) => {
      doc.setFont("helvetica", style);
      doc.setFontSize(size);
      if (color) doc.setTextColor(...color);
    };
    const setFill = rgb => doc.setFillColor(...rgb);
    const setDraw = rgb => doc.setDrawColor(...rgb);
    const fmt = v => "Rs." + Number(v).toLocaleString("en-IN", {
