actionConfiguration.body:
() => {
  const lines = getBulkInvoiceLines.data || [];
  if (lines.length === 0) {
    showAlert("No data found for this scheme in selection.", "warning");
    return;
  }
  const prodData = Scheme_Reports.getProductSummary(lines);
  const custData = Scheme_Reports.getCustomerSummary(lines);
  const dseData = Scheme_Reports.getDSESummary(lines);
  const tierData = Scheme_Reports.getTierSummary(lines);
  const auditData = Scheme_Reports.getInvoiceSummary(lines);
  storeValue('report_products', prodData);
  storeValue('report_customers', custData);
  storeValue('report_dse', dseData);
  storeValue('report_tiers', tierData);
  storeValue('report_audit', auditData);
  showAlert(`Generated 5 Scheme-Focused reports!`, "success");
}

