actionConfiguration.body:
async () => {
  const module = SelectModule.selectedOptionValue;
  const uploadData = FilePickerImport.files[0]?.data;
  if (!uploadData || uploadData.length === 0) {
    return showAlert("Please upload a filled CSV file first.", "error");
  }
  const cleanedData = uploadData.map(row => {
    const newRow = {
      ...row
    };
    if (newRow.bill_date) newRow.bill_date = Migration_Utils.formatDate(newRow.bill_date);
    if (newRow.invoice_date) newRow.invoice_date = Migration_Utils.formatDate(newRow.invoice_date);
    if (newRow.loan_date) newRow.loan_date = Migration_Utils.formatDate(newRow.loan_date);
    if (newRow.advance_date) newRow.advance_date = Migration_Utils.formatDate(newRow.advance_date);
    if (newRow.expiry_date) newRow.expiry_date = Migration_Utils.formatDate(newRow.expiry_date);
    return newRow;
  });
  try {
    switch (module) {
      case "Customers":
        await BulkImport_Customers.run({
          data: cleanedData
        });
        break;
      case "Vendors":
        await BulkImport_Vendors.run({
          data: cleanedData
        });
        break;
      case "OpeningStock":
        await BulkImport_Inventory.run({
          data: cleanedData
        });
        break;
      case "OutstandingInvoices":
        await BulkImport_Invoices.run({
          data: cleanedData
        });
        break;
      case "OutstandingBills":
        await BulkImport_Bills.run({
          data: cleanedData
        });
        break;
      case "CustomerAdvances":
        await BulkImport_CustAdvances.run({
          data: cleanedData
        });
        break;
      case "VendorAdvances":
        await BulkImport_VendAdvances.run({
          data: cleanedData
        });
        break;
      case "Loans":
        await BulkImport_Loans.run({
          data: cleanedData
        });
        break;
    }
    showAlert(`Successfully imported ${cleanedData.length} records into ${module}!`, "success");
    resetWidget("FilePickerImport", true);
  } catch (error) {
    showAlert(`Import Failed: ${error.message}`, "error");
  }
}

