async () => {
  try {
    const data = tblRecievables.tableData;
    if (!data || data.length === 0) throw new Error("No data available to download.");
    const selectedDseName = SelectDse.selectedOptionValue;
    const dseDetails = getEmployees.data.find(emp => emp.full_name === selectedDseName) || ({});
    const sortedData = [...data].sort((a, b) => {
      const nameA = (a.customer_name || "").toUpperCase();
      const nameB = (b.customer_name || "").toUpperCase();
      if (nameA < nameB) return -1;
      if (nameA > nameB) return 1;
      return new Date(a.invoice_date) - new Date(b.invoice_date);
    });
    const osTotal = sortedData.reduce((sum, item) => sum + Number(item.balance || 0), 0);
    const invCount = sortedData.length;
    const custCount = [...new Set(sortedData.map(i => i.customer_id))].length;
    const above21DaysAmt = sortedData.filter(i => i.days_from_billed > 21).reduce((s, i) => s + Number(i.balance), 0);
    const targetAmt = osTotal * 0.30;
    if (typeof jspdf === "undefined") throw new Error("jspdf library not loaded.");
    const jsPDFConstructor = jspdf.jsPDF || jspdf;
    const doc = new jsPDFConstructor('p', 'pt', 'a4');
    const brand = Global_Assets.getSummary();
    const margin = 5;
    const pageWidth = doc.internal.pageSize.width;
    const pageHeight = doc.internal.pageSize.height;
    const drawTopSection = () => {
      const headerY = margin;
      try {
        const logo = Global_Assets.getLogo();
        if (logo.startsWith("data:image/")) {
          doc.addImage(logo, 'PNG', margin, headerY, 80, 25);
        }
      } catch (e) {}
      doc.setTextColor(0, 0, 0);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(14);
      doc.text("PAYMENT COLLECTION MASTER", pageWidth / 2, headerY + 12, {
        align: "center"
      });
      const boxesY = headerY + 35;
      const gap = 5;
      const boxWidth = (pageWidth - margin * 2 - gap * 2) / 3;
      const boxHeight = 50;
      JS_Receivables._drawSimpleBox(doc, margin, boxesY, boxWidth, boxHeight, [["COMPANY", String(brand.regt_name)], ["GST", String(brand.gst)], ["CONTACT", String(brand.contact_no)], ["EMAIL", String(brand.email)]]);
      JS_Receivables._drawSimpleBox(doc, margin + boxWidth + gap, boxesY, boxWidth, boxHeight, [["DSE CODE", String(dseDetails.employee_code || "-")], ["DSE NAME", selectedDseName || "ALL SALES"], ["ROUTE", SelectRoute.selectedOptionValue || "ALL ROUTES"], ["DATE", moment().format("DD/MM/YYYY")]]);
      JS_Receivables._drawSimpleBox(doc, margin + boxWidth * 2 + gap * 2, boxesY, boxWidth, boxHeight, [["O/S TOTAL", `Rs. ${osTotal.toFixed(0)}`], ["INV/CUST", `${invCount} / ${custCount}`], ["> 21 DAYS", `Rs. ${above21DaysAmt.toFixed(0)}`], ["TARGET 30%", `Rs. ${targetAmt.toFixed(0)}`]]);
      const reconY = boxesY + boxHeight + 5;
      doc.autoTable({
        startY: reconY,
        margin: {
          left: margin
        },
        tableWidth: boxWidth,
        head: [["DENOMINATION", "QTY", "AMOUNT"]],
        body: [["500", "", ""], ["200", "", ""], ["100", "", ""], ["50", "", ""], ["20", "", ""], ["10", "", ""], ["Others", "", ""], ["TOTAL CASH", "", ""]],
        theme: 'grid',
        styles: {
          fontSize: 7,
          cellPadding: 3,
          lineColor: [0, 0, 0],
          textColor: [0, 0, 0],
          minCellHeight: 18
        },
        headStyles: {
          fillColor: [255, 255, 255],
          textColor: [0, 0, 0],
          fontStyle: 'bold',
          lineWidth: 0.5,
          lineColor: [0, 0, 0]
        }
      });
      doc.autoTable({
        startY: reconY,
        margin: {
          left: margin + boxWidth + gap
        },
        tableWidth: boxWidth * 2 + gap,
        head: [["COLLECTION SUMMARY", "AMOUNT"]],
        body: [["TOTAL CASH RECEIPT", ""], ["CHEQUE TOTAL", ""], ["ONLINE / UPI TOTAL", ""], ["EXPENSES (IF ANY)", ""], ["GRAND TOTAL COLLECTED", ""]],
        theme: 'grid',
        styles: {
          fontSize: 7,
          cellPadding: 3,
          minCellHeight: 27,
          lineColor: [0, 0, 0],
          textColor: [0, 0, 0],
          valign: 'middle'
        },
        headStyles: {
          fillColor: [255, 255, 255],
          textColor: [0, 0, 0],
          fontStyle: 'bold',
          lineWidth: 0.5,
          lineColor: [0, 0, 0]
        }
      });
      return doc.lastAutoTable.finalY + 2.5;
    };
    const firstPageTableStart = drawTopSection();
    doc.autoTable({
      startY: firstPageTableStart,
      margin: {
        left: margin,
        right: margin,
        bottom: 13,
        top: 5
      },
      head: [["Date", "Inv No", "Customer", "Amt", "Bal", "P.Date", "Mode", "Bank/Ref No", "Paid", "D"]],
      body: sortedData.map(row => [moment(row.invoice_date).format("DD/MM/YY"), row.invoice_number.replace("INV-26-", ""), row.customer_name, Number(row.bill_amount).toFixed(0), Number(row.balance).toFixed(0), "", "", "", "", row.days_from_billed]),
      didDrawPage: data => {
        doc.setFontSize(6);
        doc.setTextColor(100);
        doc.setFont("helvetica", "normal");
        const footerText = `Page ${data.pageNumber}`;
        const timestamp = `Generated on: ${moment().format("DD MMM YYYY, hh:mm A")}`;
        doc.text(footerText, pageWidth - margin - 30, pageHeight - 5);
        doc.text(timestamp, margin, pageHeight - 5);
      },
      theme: 'grid',
      styles: {
        fontSize: 7.5,
        cellPadding: 3,
        lineColor: [0, 0, 0],
        lineWidth: 0.5,
        minCellHeight: 20,
        textColor: [0, 0, 0],
        valign: 'middle'
      },
      headStyles: {
        fillColor: [255, 255, 255],
        textColor: [0, 0, 0],
        fontStyle: 'bold'
      },
      columnStyles: {
        0: {
          cellWidth: 48
        },
        1: {
          cellWidth: 42
        },
        2: {
          cellWidth: 'auto'
        },
        3: {
          halign: 'right',
          cellWidth: 38
        },
        4: {
          halign: 'right',
          cellWidth: 38
        },
        5: {
          cellWidth: 48
        },
        6: {
          cellWidth: 38
        },
        7: {
          cellWidth: 65
        },
        8: {
          cellWidth: 42
        },
        9: {
          halign: 'center',
          cellWidth: 18
        }
      }
    });
    download(doc.output('dataurlstring'), `Collection_${selectedDseName || 'Global'}.pdf`, "application/pdf");
  } catch (error) {
    showAlert("PDF Error: " + error.message, "error");
  }
}

