actionConfiguration.body:
async function (pnlData) {
  try {
    if (!pnlData) throw new Error("No P&L data provided.");
    if (typeof jspdf === "undefined") throw new Error("jspdf library not loaded.");
    const jsPDFConstructor = jspdf.jsPDF || jspdf;
    const doc = new jsPDFConstructor('p', 'pt', 'a4');
    if (typeof doc.autoTable !== "function" && jspdf.plugin && jspdf.plugin.autotable) {
      jsPDFConstructor.API.autoTable = jspdf.plugin.autotable;
    }
    const brand = Global_Assets.getSummary();
    const margin = 17.5;
    const pageWidth = doc.internal.pageSize.width;
    const pageHeight = doc.internal.pageSize.height;
    const drawPnLHeader = (currentPage, totalPages) => {
      const headerY = margin + 5;
      try {
        const logo = Global_Assets.getLogo();
        if (logo.startsWith("data:image/")) {
          doc.addImage(logo, 'PNG', margin, headerY, 90, 25);
        }
      } catch (e) {}
      doc.setTextColor(40, 40, 40);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(14);
      doc.text("PROFIT & LOSS STATEMENT", pageWidth - margin, headerY + 10, {
        align: "right"
      });
      doc.setFontSize(9);
      doc.setFont("helvetica", "normal");
      doc.text(`Financial Period: ${pnlData.period.start} to ${pnlData.period.end}`, pageWidth - margin, headerY + 22, {
        align: "right"
      });
      doc.setDrawColor(230, 230, 230);
      doc.line(margin, headerY + 35, pageWidth - margin, headerY + 35);
      const boxesY = headerY + 45;
      const gap = 10;
      const boxWidth = (pageWidth - margin * 2 - gap * 2) / 3;
      const boxHeight = 50;
      DownloadPnl._drawStatBox(doc, margin, boxesY, boxWidth, boxHeight, "TOTAL REVENUE", Number(pnlData.summary.total_revenue).toLocaleString('en-IN'));
      DownloadPnl._drawStatBox(doc, margin + boxWidth + gap, boxesY, boxWidth, boxHeight, "GROSS PROFIT", Number(pnlData.summary.gross_profit).toLocaleString('en-IN'));
      const netProfitMatch = Number(pnlData.summary.net_profit) < 0;
      DownloadPnl._drawStatBox(doc, margin + boxWidth * 2 + gap * 2, boxesY, boxWidth, boxHeight, "NET PROFIT", Number(pnlData.summary.net_profit).toLocaleString('en-IN'), netProfitMatch);
      return boxesY + boxHeight + 10;
    };
    let tableData = [];
    const sections = ['revenue', 'cogs', 'operating_expenses', 'other_income'];
    sections.forEach(secKey => {
      const section = pnlData.sections[secKey];
      if (section && section.lines.length > 0) {
        tableData.push([{
          content: section.title.toUpperCase(),
          styles: {
            fontStyle: 'bold',
            fillColor: [248, 249, 250],
            textColor: [40, 40, 40]
          }
        }, {
          content: "",
          styles: {
            fillColor: [248, 249, 250]
          }
        }, {
          content: Number(section.total).toFixed(2),
          styles: {
            fontStyle: 'bold',
            halign: 'right',
            fillColor: [248, 249, 250],
            textColor: [40, 40, 40]
          }
        }]);
        section.lines.forEach(line => {
          tableData.push([`    ${line.name}`, line.code, line.amount.toFixed(2)]);
        });
        tableData.push([{
          content: "",
          colSpan: 3,
          styles: {
            cellPadding: 1,
            border: 0
          }
        }]);
      }
    });
    doc.autoTable({
      startY: 125,
      margin: {
        left: margin,
        right: margin,
        bottom: 60
      },
      head: [["PARTICULARS", "CODE", "AMOUNT (INR)"]],
      body: tableData,
      theme: 'plain',
      styles: {
        fontSize: 8.5,
        cellPadding: 4,
        textColor: [60, 60, 60],
        lineColor: [240, 240, 240],
        lineWidth: 0.5
      },
      headStyles: {
        fillColor: [255, 255, 255],
