actionConfiguration.body:
async function (forensicData) {
  try {
    if (!forensicData) throw new Error("No forensic snapshot data provided.");
    if (typeof jspdf === "undefined") throw new Error("jspdf library not loaded.");
    const jsPDFConstructor = jspdf.jsPDF || jspdf;
    const doc = new jsPDFConstructor('p', 'pt', 'a4');
    if (typeof doc.autoTable !== "function" && jspdf.plugin && jspdf.plugin.autotable) {
      jsPDFConstructor.API.autoTable = jspdf.plugin.autotable;
    }
    const brand = Global_Assets.getSummary();
    const margin = 20;
    const pageWidth = doc.internal.pageSize.width;
    const pageHeight = doc.internal.pageSize.height;
    const drawHeader = (currentPage, totalPages) => {
      const headerY = margin + 5;
      try {
        const logo = Global_Assets.getLogo();
        if (logo && logo.startsWith("data:image/")) {
          doc.addImage(logo, 'PNG', margin, headerY, 90, 25);
        }
      } catch (e) {}
      doc.setTextColor(30, 41, 59);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(14);
      doc.text("FORENSIC FINANCIAL SNAPSHOT", pageWidth - margin, headerY + 10, {
        align: "right"
      });
      doc.setFontSize(8.5);
      doc.setFont("helvetica", "normal");
      doc.setTextColor(100, 116, 139);
      const generatedDate = moment(forensicData.timestamp).format("DD MMM YYYY, hh:mm A");
      doc.text(`Snapshot Generated: ${generatedDate}`, pageWidth - margin, headerY + 22, {
        align: "right"
      });
      doc.setDrawColor(226, 232, 240);
      doc.line(margin, headerY + 32, pageWidth - margin, headerY + 32);
      const boxesY = headerY + 40;
      const gap = 10;
      const boxWidth = (pageWidth - margin * 2 - gap * 2) / 3;
      const boxHeight = 50;
      JSObject1._drawStatBox(doc, margin, boxesY, boxWidth, boxHeight, "TOTAL REAL ASSETS", `INR ${Number(forensicData.summary.total_assets).toLocaleString('en-IN', {
        minimumFractionDigits: 2
      })}`);
      JSObject1._drawStatBox(doc, margin + boxWidth + gap, boxesY, boxWidth, boxHeight, "TOTAL LIABILITIES", `INR ${Number(forensicData.summary.total_liabilities).toLocaleString('en-IN', {
        minimumFractionDigits: 2
      })}`);
      const netCapital = Number(forensicData.summary.net_capital);
      JSObject1._drawStatBox(doc, margin + boxWidth * 2 + gap * 2, boxesY, boxWidth, boxHeight, "NET CAPITAL (EQUITY)", `INR ${netCapital.toLocaleString('en-IN', {
        minimumFractionDigits: 2
      })}`, netCapital < 0);
      return boxesY + boxHeight + 15;
    };
    const liquidRows = (forensicData.accounts || []).map(acc => [acc.name, acc.category, Number(acc.balance).toLocaleString('en-IN', {
      minimumFractionDigits: 2
    })]);
    const partyRows = [];
    (forensicData.receivables || []).slice(0, 5).forEach(r => {
      partyRows.push([r.party, "Receivable (Customer)", `${r.pending_bills} Bills`, Number(r.balance).toLocaleString('en-IN', {
        minimumFractionDigits: 2
      })]);
    });
    (forensicData.payables || []).slice(0, 5).forEach(p => {
      partyRows.push([p.party, "Payable (Vendor)", "-", Number(p.balance).toLocaleString('en-IN', {
        minimumFractionDigits: 2
      })]);
    });
    const loanRows = [];
    (forensicData.loans_given || []).forEach(l => {
      loanRows.push([l.party_name, "LOAN GIVEN (Asset)", l.status, Number(l.balance).toLocaleString('en-IN', {
        minimumFractionDigits: 2
      })]);
    });
    (forensicData.loans_taken || []).forEach(l => {
      loanRows.push([l.party_name, "LOAN TAKEN (Liability)", l.status, Number(l.balance).toLocaleString('en-IN', {
        minimumFractionDigits: 2
      })]);
    });
    const assetRows = [];
    (forensicData.stock || []).slice(0, 5).forEach(s => {
      assetRows.push([s.product_name, "Inventory (Stock)", `${Number(s.stock_qty).toLocaleString()} Units`, Number(s.valuation).toLocaleString('en-IN', {
        minimumFractionDigits: 2
      })]);
