async function (salaryData) {
  try {
    if (!salaryData || !salaryData.header) throw new Error("No Salary/Payslip data loaded.");
    if (typeof jspdf === "undefined") throw new Error("jsPDF library not loaded. Add it in App Settings → External Libraries.");
    const jsPDFConstructor = jspdf.jsPDF || jspdf;
    const doc = new jsPDFConstructor("p", "pt", "a4");
    if (typeof doc.autoTable !== "function" && jspdf.plugin && jspdf.plugin.autotable) {
      jsPDFConstructor.API.autoTable = jspdf.plugin.autotable;
    }
    const h = salaryData.header;
    const breakdown = salaryData.breakdown || ({});
    const company = Global_Assets.getSummary();
    const logo = Global_Assets.getLogo();
    const PW = doc.internal.pageSize.width;
    const PH = doc.internal.pageSize.height;
    const ML = 16;
    const MR = 16;
    const CW = PW - ML - MR;
    const C = {
      primaryIndigo: [79, 70, 229],
      accentCoral: [249, 115, 22],
      textDark: [15, 23, 42],
      textSlate: [71, 85, 105],
      textLight: [148, 163, 184],
      webBg: [248, 250, 252],
      netSalaryBg: [238, 242, 255],
      cardBorder: [226, 232, 240],
      emerald: [16, 185, 129],
      rose: [244, 63, 94],
      bannerPeach: [255, 247, 237]
    };
    const setFont = (style, size, color) => {
      doc.setFont("helvetica", style);
      doc.setFontSize(size);
      if (color) doc.setTextColor(...color);
    };
    const setFill = rgb => doc.setFillColor(...rgb);
    const setDraw = rgb => doc.setDrawColor(...rgb);
    const fmt = v => "Rs." + Number(v).toLocaleString("en-IN", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
    const fmtN = v => Number(v).toLocaleString("en-IN");
    const getMonthName = mNum => {
      const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
      return months[mNum - 1] || "Month";
    };
    const toWords = num => {
      const a = ['', 'One ', 'Two ', 'Three ', 'Four ', 'Five ', 'Six ', 'Seven ', 'Eight ', 'Nine ', 'Ten ', 'Eleven ', 'Twelve ', 'Thirteen ', 'Fourteen ', 'Fifteen ', 'Sixteen ', 'Seventeen ', 'Eighteen ', 'Nineteen '];
      const b = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
      const n = ("000000000" + Math.floor(num)).substr(-9).match(/^(\d{2})(\d{2})(\d{2})(\d{1})(\d{2})$/);
      if (!n) return '';
      let str = '';
      str += Number(n[1]) != 0 ? (a[Number(n[1])] || b[n[1][0]] + ' ' + a[n[1][1]]) + 'Crore ' : '';
      str += Number(n[2]) != 0 ? (a[Number(n[2])] || b[n[2][0]] + ' ' + a[n[2][1]]) + 'Lakh ' : '';
      str += Number(n[3]) != 0 ? (a[Number(n[3])] || b[n[3][0]] + ' ' + a[n[3][1]]) + 'Thousand ' : '';
      str += Number(n[4]) != 0 ? (a[Number(n[4])] || b[n[4][0]] + ' ' + a[n[4][1]]) + 'Hundred ' : '';
      str += Number(n[5]) != 0 ? (str != '' ? 'and ' : '') + (a[Number(n[5])] || b[n[5][0]] + ' ' + a[n[5][1]]) + 'Only ' : 'Only ';
      return str;
    };
    let Y = 20;
    setFill(C.primaryIndigo);
    doc.rect(0, 0, PW, 6, "F");
    try {
      if (logo && logo.startsWith("data:image/")) {
        doc.addImage(logo, "PNG", ML, Y, 85, 26);
      }
    } catch (e) {}
    setFont("bold", 12, C.textDark);
    doc.text(company.regt_name, PW - MR, Y + 10, {
      align: "right"
    });
    setFont("normal", 8, C.textSlate);
    doc.text(`${company.address} | GSTIN: ${company.gst}`, PW - MR, Y + 22, {
      align: "right"
    });
    Y += 40;
    setDraw(C.cardBorder);
    doc.setLineWidth(0.75);
    doc.line(ML, Y, PW - MR, Y);
    Y += 12;
    const salaryPeriod = `${getMonthName(h.month).toUpperCase()} ${h.year}`;
    setFill(C.bannerPeach);
    setDraw([251, 146, 60]);
    doc.setLineWidth(0.5);
    doc.roundedRect(ML, Y, CW, 30, 4, 4, "FD");
    setFont("bold", 10.5, C.accentCoral);
    doc.text(`SALARY CREDIT ADVICE — ${salaryPeriod}`, ML + 12, Y + 19);
    setFont("bold", 9, C.textSlate);
    doc.text(`REFERENCE ID: PAY-${h.id}`, PW - MR - 12, Y + 19, {
      align: "right"
    });
    Y += 42;
    setFill(C.webBg);
    setDraw(C.cardBorder);
    doc.roundedRect(ML, Y, CW, 65, 4, 4, "FD");
    setFont("bold", 7.5, C.textSlate);
    doc.text("EMPLOYEE DETAILS", ML + 15, Y + 16);
    setFont("normal", 8.5, C.textSlate);
    doc.text("Name:", ML + 15, Y + 30);
    doc.text("Emp Code:", ML + 15, Y + 44);
    doc.text("Joining Date:", ML + 15, Y + 56);
    setFont("bold", 9, C.textDark);
    doc.text(String(h.full_name), ML + 80, Y + 30);
    setFont("normal", 9, C.textDark);
    doc.text(String(h.employee_code), ML + 80, Y + 44);
    doc.text(h.joining_date ? h.joining_date.slice(0, 10) : "-", ML + 80, Y + 56);
    setDraw(C.cardBorder);
    doc.line(ML + 270, Y + 10, ML + 270, Y + 55);
    setFont("bold", 7.5, C.textSlate);
    doc.text("TRANSACTION DETAILS", ML + 285, Y + 16);
    setFont("normal", 8.5, C.textSlate);
    doc.text("Credit Date:", ML + 285, Y + 30);
    doc.text("Mode / Source:", ML + 285, Y + 44);
    doc.text("Journal Entry:", ML + 285, Y + 56);
    setFont("normal", 9, C.textDark);
    doc.text(h.payment_date ? h.payment_date.slice(0, 10) : "-", ML + 375, Y + 30);
    doc.text(`${h.payment_mode} (${h.source_account})`, ML + 375, Y + 44);
    doc.text(String(h.journal_entry_id || "-"), ML + 375, Y + 56);
    Y += 80;
    doc.autoTable({
      startY: Y,
      margin: {
        left: ML,
        right: MR
      },
      head: [["EARNINGS & ADDITIONS", "AMOUNT (Rs.)", "DEDUCTIONS & RECOVERIES", "AMOUNT (Rs.)"]],
      body: [["Basic Salary (Adjusted)", fmtN(Number(h.adjusted_base_salary).toFixed(2)), "Absentee / Leave Deductions", fmtN(Number(h.leave_deduction).toFixed(2))], ["Incentive / Bonus Additions", fmtN(Number(h.bonus_addition).toFixed(2)), "Salary Advances Recovered", fmtN(Number(h.advance_deduction).toFixed(2))], ["Leave Encashments", fmtN(Number(h.leave_encashment).toFixed(2)), "Personal Loan Deductions", fmtN(Number(h.loan_deduction).toFixed(2))], ["—", "—", "Miscellaneous / Other Deductions", fmtN(Number(h.other_deductions).toFixed(2))]],
      theme: "grid",
      styles: {
        fontSize: 8.5,
        cellPadding: 4.5,
        lineColor: C.cardBorder,
        lineWidth: 0.5,
        textColor: C.textDark,
        valign: "middle"
      },
      headStyles: {
        fillColor: C.primaryIndigo,
        textColor: [255, 255, 255],
        fontStyle: "bold",
        fontSize: 8
      },
      columnStyles: {
        0: {
          cellWidth: 180
        },
        1: {
          halign: "right",
          cellWidth: 100
        },
        2: {
          cellWidth: 180
        },
        3: {
          halign: "right",
          cellWidth: 100
        }
      },
      alternateRowStyles: {
        fillColor: [255, 255, 255]
      },
      foot: [[{
        content: "TOTAL ADDITIONS",
        styles: {
          fontStyle: "bold",
          fillColor: C.webBg
        }
      }, {
        content: fmtN(Number(h.total_additions || 0).toFixed(2)),
        styles: {
          halign: "right",
          fontStyle: "bold",
          textColor: C.emerald,
          fillColor: C.webBg
        }
      }, {
        content: "TOTAL DEDUCTIONS",
        styles: {
          fontStyle: "bold",
          fillColor: C.webBg
        }
      }, {
        content: fmtN(Number(h.total_deductions || 0).toFixed(2)),
        styles: {
          halign: "right",
          fontStyle: "bold",
          textColor: C.rose,
          fillColor: C.webBg
        }
      }]],
      footStyles: {
        lineColor: C.cardBorder,
        lineWidth: 0.5
      }
    });
    Y = doc.lastAutoTable.finalY + 16;
    const halfWidth = (CW - 16) / 2;
    const bonusRows = (breakdown.additions?.bonuses || []).map(b => [b.bonus_type, b.remarks || "Salary Incentive", fmtN(Number(b.amount).toFixed(2))]);
    if (bonusRows.length === 0) bonusRows.push(["—", "No adjustments", "0.00"]);
    const advanceRows = (breakdown.deductions?.advances || []).map(a => [a.date ? a.date.slice(5, 10) : "-", a.remarks || "Advance Recovery", fmtN(Number(a.amount).toFixed(2))]);
