  const data = utils.getMergedData();
  const payments = data.payments || [];
  let list = [];
  if (mode === 'Online') {
    list = payments.filter(p => ['NEFT', 'UPI', 'Bank Transfer', 'Online'].includes(p.payment_mode));
  } else {
