    if (typeof jspdf === "undefined") throw new Error("jspdf library not loaded.");
    const jsPDFConstructor = jspdf.jsPDF || jspdf;
    const doc = new jsPDFConstructor('p', 'pt', 'a4');
    const brand = Global_Assets.getSummary();
    const margin = 15;
    const pageWidth = doc.internal.pageSize.width;
    const pageHeight = doc.internal.pageSize.height;
    const drawTopSection = () => {
      const headerY = margin + 5;
      try {
        const logo = Global_Assets.getLogo();
        if (logo && logo.startsWith("data:image/")) {
          doc.addImage(logo, 'PNG', margin, headerY, 80, 25);
        }
      } catch (e) {}
      doc.setTextColor(0, 0, 0);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(14);
      doc.text("DELIVERY & COLLECTION SHEET", pageWidth / 2, headerY + 15, {
        align: "center"
      });
      const boxesY = headerY + 35;
      const gap = 10;
      const boxWidth = (pageWidth - margin * 2 - gap * 2) / 3;
      const boxHeight = 55;
      TripReports._drawSimpleBox(doc, margin, boxesY, boxWidth, boxHeight, [["COMPANY", String(brand.regt_name)], ["GST", String(brand.gst)], ["CONTACT", String(brand.contact_no)], ["EMAIL", String(brand.email)]]);
      TripReports._drawSimpleBox(doc, margin + boxWidth + gap, boxesY, boxWidth, boxHeight, [["TEAM", String(tripInfo.team)], ["DRIVER", String(tripInfo.driver_name)], ["VEHICLE", String(tripInfo.vehicle_number)]]);
      const totalAmnt = data.reduce((sum, r) => sum + Number(r.grand_total || 0), 0);
      TripReports._drawSimpleBox(doc, margin + boxWidth * 2 + gap * 2, boxesY, boxWidth, boxHeight, [["TRIP NO", String(tripInfo.trip_number)], ["DATE", moment(tripInfo.date).format("DD MMM YYYY")], ["TOTAL SHOPS", `${data.length} Customers`], ["EXPECTED", `Rs. ${totalAmnt.toLocaleString('en-IN', {
        minimumFractionDigits: 0
      })}`]]);
      return boxesY + boxHeight + 2.5;
    };
    const firstPageTableStart = drawTopSection();
    doc.autoTable({
      startY: firstPageTableStart,
      margin: {
        left: margin,
        right: margin,
        bottom: 40,
        top: 2.5
      },
      head: [["SEQ", "INVOICE #", "CUSTOMER NAME", "ADDRESS/CONTACT", "BILL AMT", "COLLECTED [ ]", "REMARKS"]],
      body: data.map((row, index) => [index + 1, row.invoice_number, {
        content: row.customer_name,
        styles: {
          fontStyle: 'bold'
        }
      }, `${row.address || ""}\nPh: ${row.phone || "-"}`, {
        content: Number(row.grand_total || 0).toLocaleString('en-IN', {
          minimumFractionDigits: 2
        }),
        styles: {
          fontStyle: 'bold',
          halign: 'right'
        }
      }, "", ""]),
      didDrawPage: data => {
        doc.setFontSize(8);
        doc.setTextColor(100);
        doc.setFont("helvetica", "normal");
        const timestamp = `Generated: ${moment().format("DD MMM YYYY, hh:mm A")}`;
        doc.text(timestamp, margin, pageHeight - 15);
        doc.text(`Page ${data.pageNumber} of ${doc.internal.getNumberOfPages()}`, pageWidth - margin - 40, pageHeight - 15);
        if (data.pageNumber === doc.internal.getNumberOfPages()) {
          doc.setDrawColor(150);
          doc.setLineWidth(0.5);
          doc.line(margin, pageHeight - 40, margin + 120, pageHeight - 40);
          doc.text("Driver Signature", margin, pageHeight - 30);
          doc.line(pageWidth - margin - 120, pageHeight - 40, pageWidth - margin, pageHeight - 40);
          doc.text("Manager Signature", pageWidth - margin - 120, pageHeight - 30);
        }
      },
      theme: 'grid',
      styles: {
        fontSize: 7,
        cellPadding: 4,
        lineColor: [0, 0, 0],
        lineWidth: 0.5,
        minCellHeight: 25,
        textColor: [0, 0, 0],
        valign: 'middle'
      },
      headStyles: {
        fillColor: [255, 255, 255],
        textColor: [0, 0, 0],
        fontStyle: 'bold',
        lineWidth: 0.5,
        lineColor: [0, 0, 0]
      },
      columnStyles: {
        0: {
          cellWidth: 25
        },
        2: {
          cellWidth: 'auto'
        },
        3: {
          cellWidth: 110
        },
        4: {
          cellWidth: 60
        },
        5: {
          cellWidth: 70
        },
        6: {
          cellWidth: 70
        }
      }
    });
    download(doc.output('dataurlstring'), `DeliverySheet_${tripInfo.trip_number}.pdf`, "application/pdf");
  } catch (e) {
    showAlert("Delivery Error: " + e.message, "error");
  }
}

