actionConfiguration.body:
async cnHeader => {
  try {
    if (!cnHeader || !cnHeader.id) throw new Error("No Credit Note data selected.");
    if (typeof jspdf === "undefined") throw new Error("jspdf library not loaded.");
    const jsPDFConstructor = jspdf.jsPDF || jspdf;
    const doc = new jsPDFConstructor('p', 'pt', 'a4');
    if (typeof doc.autoTable !== "function" && jspdf.plugin && jspdf.plugin.autotable) {
      jsPDFConstructor.API.autoTable = jspdf.plugin.autotable;
    }
    const cnLines = cnHeader.items || [];
    const summaryData = CreditNoteManager.getTaxSummary(cnLines);
    const grandTotal = Number(cnHeader.amount || 0);
    const brand = Global_Assets.getSummary();
    const margin = 12;
    const pageWidth = doc.internal.pageSize.width;
    const pageHeight = doc.internal.pageSize.height;
    const toWords = num => {
      const a = ['', 'One ', 'Two ', 'Three ', 'Four ', 'Five ', 'Six ', 'Seven ', 'Eight ', 'Nine ', 'Ten ', 'Eleven ', 'Twelve ', 'Thirteen ', 'Fourteen ', 'Fifteen ', 'Sixteen ', 'Seventeen ', 'Eighteen ', 'Nineteen '];
      const b = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
      const n = ("000000000" + Math.floor(num)).substr(-9).match(/^(\d{2})(\d{2})(\d{2})(\d{1})(\d{2})$/);
      if (!n) return '';
      let str = '';
      str += Number(n[1]) != 0 ? (a[Number(n[1])] || b[n[1][0]] + ' ' + a[n[1][1]]) + 'Crore ' : '';
      str += Number(n[2]) != 0 ? (a[Number(n[2])] || b[n[2][0]] + ' ' + a[n[2][1]]) + 'Lakh ' : '';
      str += Number(n[3]) != 0 ? (a[Number(n[3])] || b[n[3][0]] + ' ' + a[n[3][1]]) + 'Thousand ' : '';
      str += Number(n[4]) != 0 ? (a[Number(n[4])] || b[n[4][0]] + ' ' + a[n[4][1]]) + 'Hundred ' : '';
      str += Number(n[5]) != 0 ? (str != '' ? 'and ' : '') + (a[Number(n[5])] || b[n[5][0]] + ' ' + a[n[5][1]]) + 'Only ' : 'Only ';
      return str;
    };
    const drawMainHeader = (currentPage, totalPages) => {
      const headerY = margin;
      try {
        const logo = Global_Assets.getLogo();
        if (logo.startsWith("data:image/")) {
          doc.addImage(logo, 'PNG', margin, headerY, 90, 30);
        }
      } catch (e) {}
      doc.setTextColor(0, 0, 0);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(16);
      doc.text("CREDIT NOTE", pageWidth / 2, headerY + 15, {
        align: "center"
      });
      doc.setFontSize(11);
      doc.text(String(cnHeader.return_number), pageWidth / 2, headerY + 30, {
        align: "center"
      });
      const boxesY = headerY + 40;
      const gap = 8;
      const boxWidth = (pageWidth - margin * 2 - gap * 2) / 3;
      const boxHeight = 85;
      CreditNoteManager._drawSimpleBox(doc, margin, boxesY, boxWidth, boxHeight, [["CN NUMBER", String(cnHeader.return_number)], ["DATE", moment(cnHeader.return_date).format("DD/MM/YYYY")], ["LINKED INV", String(cnHeader.linked_invoice_number || "-")], ["TOTAL AMT", Number(grandTotal).toFixed(2)], ["PAGE", `${currentPage} / ${totalPages}`]]);
      CreditNoteManager._drawSimpleBox(doc, margin + boxWidth + gap, boxesY, boxWidth, boxHeight, [["From", String(brand.regt_name)], ["Address", String(brand.address)], ["Dist/PIN", `${brand.District} - ${brand.pin}`], ["GST", String(brand.gst)], ["FSSAI", String(brand.fssai_no)], ["Email", String(brand.email)], ["Contact No", String(brand.contact_no)]]);
      const cArr = [cnHeader.customer_address, cnHeader.customer_district, cnHeader.customer_pin ? "PIN: " + cnHeader.customer_pin : null].filter(Boolean).join(", ");
      CreditNoteManager._drawSimpleBox(doc, margin + boxWidth * 2 + gap * 2, boxesY, boxWidth, boxHeight, [["Customer", String(cnHeader.customer_name)], ["Address", cArr || "-"], ["GST", String(cnHeader.customer_gst || "-")], ["Contact", String(cnHeader.customer_contact || "-")], ["Email", String(cnHeader.customer_email || "-")]]);
      return boxesY + boxHeight;
    };
    doc.autoTable({
      startY: margin + 40 + 85 + 10,
      margin: {
        left: margin,
        right: margin,
        top: margin + 140,
        bottom: 120
      },
      head: [["S.N", "ITEM NAME", "CODE\nEAN", "HSN", "BATCH\nEXPIRY", "MRP", "QTY", "PRICE", "GROSS", "SCH", "D%", "D.AMT", "TXBL", "GST%", "GST$", "NET$"]],
      body: cnLines.map((row, index) => {
        const expiryStr = row['Expiry'] ? moment(row['Expiry']).format("MM/YY") : "-";
        return [index + 1, row['Item Name'], `${row['product_code'] || ""}\n${row['EAN Code'] || ""}`, row['hsn_code'] || "-", `${row['Batch No'] || ""}\n${expiryStr}`, Number(row['MRP'] || 0).toFixed(2), row['Qty'], Number(row['Price'] || 0).toFixed(2), Number(row['Gross $'] || 0).toFixed(2), Number(row['Sch'] || 0).toFixed(2), row['Disc %'] || "0%", Number(row['Disc. $'] || 0).toFixed(2), Number(row['Taxable $'] || 0).toFixed(2), (row['GST %'] || 0) + "%", Number(row['GST $'] || 0).toFixed(2), Number(row['Net $'] || 0).toFixed(2)];
      }),
      didDrawPage: data => {
        const totalPages = doc.internal.getNumberOfPages();
        drawMainHeader(data.pageNumber, totalPages);
      },
      theme: 'grid',
      styles: {
        fontSize: 6,
        cellPadding: 2,
        lineColor: [0, 0, 0],
        lineWidth: 0.5,
        textColor: [0, 0, 0],
        valign: 'middle'
      },
      headStyles: {
        fillColor: [255, 255, 255],
        textColor: [0, 0, 0],
        fontStyle: 'bold',
        lineWidth: 0.5,
        valign: 'middle'
      },
      columnStyles: {
        0: {
          cellWidth: 15
        },
        1: {
          cellWidth: 'auto',
          minCellWidth: 80
        },
        2: {
          cellWidth: 40
        },
        3: {
          cellWidth: 30
        },
        4: {
          cellWidth: 40
        },
        5: {
          halign: 'right'
        },
        6: {
          halign: 'right'
        },
        7: {
          halign: 'right'
        },
        8: {
          halign: 'right'
        },
        9: {
          halign: 'right'
        },
        10: {
          halign: 'right'
        },
        11: {
          halign: 'right'
        },
        12: {
          halign: 'right'
        },
        13: {
          halign: 'center'
        },
        14: {
          halign: 'right'
        },
        15: {
          halign: 'right'
        }
      }
    });
    let currentY = doc.lastAutoTable.finalY + 8;
    if (currentY + 150 > pageHeight) {
      doc.addPage();
      const totalPages = doc.internal.getNumberOfPages();
      currentY = drawMainHeader(totalPages, totalPages) + 10;
    }
    doc.autoTable({
      startY: currentY,
      margin: {
        left: margin
      },
      head: [["TAX SUMMARY", "PCS", "GROSS", "SCH", "DISC", "TAXABLE", "TAX", "NET"]],
      body: summaryData.map(row => [row.PARTICULARS, row.Pcs, row.Gross.toFixed(2), row.Sch.toFixed(2), row.Disc.toFixed(2), row.Taxable.toFixed(2), row.Tax.toFixed(2), row.Net.toFixed(2)]),
      theme: 'grid',
      styles: {
        fontSize: 7.5,
        cellPadding: 2,
        lineColor: [0, 0, 0],
        lineWidth: 0.5,
        textColor: [0, 0, 0],
        valign: 'middle'
      },
      headStyles: {
        fillColor: [255, 255, 255],
        textColor: [0, 0, 0],
        fontStyle: 'bold'
      }
    });
    const wordsY = doc.lastAutoTable.finalY + 25;
    doc.setFontSize(11);
    doc.setFont("helvetica", "bold");
    doc.text("Total Amount (in words):", margin, wordsY);
    doc.setFont("helvetica", "normal");
    doc.text(toWords(Math.round(grandTotal)), margin + 140, wordsY);
    const slipY = pageHeight - 110;
    doc.setLineDash([3, 3], 0);
    doc.line(margin, slipY, pageWidth - margin, slipY);
    doc.setLineDash([], 0);
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.text("DETACHABLE ACKNOWLEDGEMENT SLIP", pageWidth / 2, slipY + 20, {
      align: "center"
    });
    const slipContentY = slipY + 45;
    doc.setFont("helvetica", "normal");
    doc.text(`Credit Note: ${cnHeader.return_number}`, margin, slipContentY);
    doc.text(`Date: ${moment(cnHeader.return_date).format("DD/MM/YYYY")}`, margin + 180, slipContentY);
    doc.text(`Amt: ${grandTotal.toFixed(2)}`, margin + 350, slipContentY);
    doc.text(`Customer: ${cnHeader.customer_name}`, margin, slipContentY + 20);
    doc.text(`Auth. Signature: ___________________________`, margin + 310, slipContentY + 35);
    const fileName = (cnHeader.return_number || "CreditNote") + ".pdf";
    download(doc.output('dataurlstring'), fileName, "application/pdf");
    showAlert("Credit Note PDF Downloaded", "success");
  } catch (error) {
    showAlert("PDF Error: " + error.message, "error");
  }
}

