jsonPathKeys:
function (rows) {
  const groups = {};
  rows.forEach(raw => {
    const row = InvoiceUtils.normalizeRow(raw);
    const key = row.invoice_number;
    if (!key) return;
    if (!groups[key]) {
      const fallback = InvoiceUtils.getCustomerDetails(row.customer_id);
      groups[key] = {
        invoice_id: row.invoice_id || key,
        invoice_number: row.invoice_number,
        invoice_date: row.invoice_date,
        order_date: row.invoice_date,
        customer_id: row.customer_id,
        customer_name: row.customer_name,
        customer_address: row.customer_address || fallback.customer_address,
        district: row.district || fallback.district,
        pin_code: row.pin_code || fallback.pin_code,
        gstin: row.gstin || fallback.gstin,
        customer_phone: row.customer_phone || fallback.customer_phone,
        customer_email: row.customer_email || fallback.customer_email,
        dse_name: row.dse_name || fallback.dse_name,
        dse_phone: row.dse_phone || fallback.dse_phone,
        route: row.route || fallback.route,
        grand_total: 0,
        invoice_lines: []
      };
    }
    const g = groups[key];
    if (row.invoice_date && new Date(row.invoice_date) > new Date(g.invoice_date)) {
      g.invoice_date = row.invoice_date;
      g.order_date = row.invoice_date;
    }
    g.invoice_lines.push({
      product_name: row.product_name,
      ean_code: row.ean_code || "-",
      hsn_code: row.hsn_code || "-",
      batch_code: row.batch_code || "-",
      expiry_date: row.expiry_date || null,
      mrp: row.mrp || row.selling_rate || 0,
      shipped_qty: row.shipped_qty,
      rate: row.selling_rate,
      gross_amount: row.gross_amount,
      scheme_amount: row.scheme_amount,
      discount_percent: row.discount_percent,
      discount_amount: row.discount_amount,
      taxable_amount: row.taxable_sales_value,
      tax_percent: row.tax_percent,
      tax_amount: row.tax_amount,
      amount: row.net_sales_value,
      tier_applied: row.tier_applied || (row.scheme_amount > 0 ? "Scheme Applied" : null)
    });
    g.grand_total += Number(row.net_sales_value || 0);
  });
  Object.values(groups).forEach(g => {
    g.grand_total = Math.round(g.grand_total * 100) / 100;
  });
  return groups;
}

