actionConfiguration.body:
async function (fileData) {
  try {
    if (!fileData || fileData.length === 0) {
      throw new Error("No data found. Please upload a file first.");
    }
    const grouped = InvoiceUtils.groupRows(fileData);
    const invoiceNumbers = Object.keys(grouped);
    if (invoiceNumbers.length === 0) {
      throw new Error("No valid invoice_number found in the uploaded file.");
    }
    for (let i = 0; i < invoiceNumbers.length; i++) {
      const invNo = invoiceNumbers[i];
      await InvoiceUtils.previewInvoice(grouped[invNo]);
      if (i < invoiceNumbers.length - 1) {
        await new Promise(resolve => setTimeout(resolve, 700));
      }
    }
    showAlert(`Generated ${invoiceNumbers.length} invoice(s) successfully`, "success");
  } catch (error) {
    showAlert("Bulk Invoice Error: " + error.message, "error");
  }
}

