actionConfiguration.body:
async function (invoiceData) {
  try {
    if (!invoiceData || !invoiceData.invoice_id) throw new Error("No Invoice data selected.");
    if (typeof jspdf === "undefined") throw new Error("jspdf library not loaded.");
    const jsPDFConstructor = jspdf.jsPDF || jspdf;
    const doc = new jsPDFConstructor('p', 'pt', 'a4');
    if (typeof doc.autoTable !== "function" && jspdf.plugin && jspdf.plugin.autotable) {
      jsPDFConstructor.API.autoTable = jspdf.plugin.autotable;
    }
    const lines = invoiceData.invoice_lines || [];
    const summaryData = InvoiceUtils.getSummary(lines);
    const grandTotal = Number(invoiceData.grand_total || 0);
    const brand = Global_Assets.getSummary();
    await getBankDetails.run();
    const bank = getBankDetails.data || ({});
    const margin = 12;
    const pageWidth = doc.internal.pageSize.width;
    const toWords = num => {
      const a = ['', 'One ', 'Two ', 'Three ', 'Four ', 'Five ', 'Six ', 'Seven ', 'Eight ', 'Nine ', 'Ten ', 'Eleven ', 'Twelve ', 'Thirteen ', 'Fourteen ', 'Fifteen ', 'Sixteen ', 'Seventeen ', 'Eighteen ', 'Nineteen '];
      const b = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
      const n = ("000000000" + Math.floor(num)).substr(-9).match(/^(\d{2})(\d{2})(\d{2})(\d{1})(\d{2})$/);
      if (!n) return '';
      let str = '';
      str += Number(n[1]) != 0 ? (a[Number(n[1])] || b[n[1][0]] + ' ' + a[n[1][1]]) + 'Crore ' : '';
      str += Number(n[2]) != 0 ? (a[Number(n[2])] || b[n[2][0]] + ' ' + a[n[2][1]]) + 'Lakh ' : '';
      str += Number(n[3]) != 0 ? (a[Number(n[3])] || b[n[3][0]] + ' ' + a[n[3][1]]) + 'Thousand ' : '';
      str += Number(n[4]) != 0 ? (a[Number(n[4])] || b[n[4][0]] + ' ' + a[n[4][1]]) + 'Hundred ' : '';
      str += Number(n[5]) != 0 ? (str != '' ? 'and ' : '') + (a[Number(n[5])] || b[n[5][0]] + ' ' + a[n[5][1]]) + 'Only ' : 'Only ';
      return str;
    };
    const drawMainHeader = (currentPage, totalPages) => {
      const headerY = margin;
      try {
        const logo = Global_Assets.getLogo();
        if (logo.startsWith("data:image/")) {
          doc.addImage(logo, 'PNG', margin, headerY, 90, 30);
        }
      } catch (e) {}
      doc.setTextColor(0, 0, 0);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(16);
      doc.text("SALES INVOICE", pageWidth / 2, headerY + 15, {
        align: "center"
      });
      doc.setFontSize(11);
      doc.text(String(invoiceData.invoice_number), pageWidth / 2, headerY + 30, {
        align: "center"
      });
      const boxesY = headerY + 40;
      const gap = 8;
      const boxWidth = (pageWidth - margin * 2 - gap * 2) / 3;
      const boxHeight = 95;
      InvoiceUtils._drawSimpleBox(doc, margin, boxesY, boxWidth, boxHeight, [["From", String(brand.regt_name)], ["Address", String(brand.address)], ["Dist/PIN", `${brand.District} - ${brand.pin}`], ["GST", String(brand.gst)], ["FSSAI", String(brand.fssai_no)], ["Email", String(brand.email)], ["Contact No", String(brand.contact_no)]]);
      const cAddr = [invoiceData.customer_address, invoiceData.district, invoiceData.pin_code ? "PIN: " + invoiceData.pin_code : null].filter(Boolean).join(", ");
      InvoiceUtils._drawSimpleBox(doc, margin + boxWidth + gap, boxesY, boxWidth, boxHeight, [["To", String(invoiceData.customer_name)], ["Address", cAddr || "-"], ["GSTIN", String(invoiceData.gstin || "-")], ["Phone", String(invoiceData.customer_phone || "-")], ["Email", String(invoiceData.customer_email || "-")]], 60);
      InvoiceUtils._drawSimpleBox(doc, margin + boxWidth * 2 + gap * 2, boxesY, boxWidth, boxHeight, [["INV No", String(invoiceData.invoice_number)], ["Date", moment(invoiceData.invoice_date).format("DD/MM/YYYY")], ["Order Date", moment(invoiceData.order_date).format("DD/MM/YYYY")], ["TOTAL AMT", Number(grandTotal).toFixed(2)], ["DSE", String(invoiceData.dse_name || "-")], ["Route", String(invoiceData.route || "-")], ["DSE Phone", String(invoiceData.dse_phone || "-")], ["PAGE", `${currentPage} / ${totalPages}`]], 65);
      return boxesY + boxHeight;
    };
    doc.autoTable({
      startY: margin + 40 + 95 + 10,
      margin: {
        left: margin,
        right: margin,
        top: 157,
        bottom: 12
      },
      head: [["S.N", "ITEM NAME", "EAN CODE", "HSN", "BATCH\nEXPIRY", "MRP", "QTY", "PRICE", "GROSS", "SCH", "D%", "D.AMT", "TXBL", "GST%", "GST$", "NET$"]],
      body: lines.map((row, index) => {
        const expiryStr = row.expiry_date ? moment(row.expiry_date).format("MM/YY") : "-";
        return [index + 1, row.product_name, row.ean_code || "-", row.hsn_code || "-", `${row.batch_code || ""}\n${expiryStr}`, Number(row.mrp || 0).toFixed(2), row.shipped_qty, Number(row.rate || 0).toFixed(2), Number(row.gross_amount || 0).toFixed(2), Number(row.scheme_amount || 0).toFixed(2), (row.discount_percent || 0) + "%", Number(row.discount_amount || 0).toFixed(2), Number(row.taxable_amount || 0).toFixed(2), (row.tax_percent || 0) + "%", Number(row.tax_amount || 0).toFixed(2), Number(row.amount || 0).toFixed(2)];
      }),
      didDrawPage: data => {
        drawMainHeader(data.pageNumber, doc.internal.getNumberOfPages());
      },
      theme: 'grid',
      styles: {
        fontSize: 8,
        cellPadding: 2,
        lineColor: [0, 0, 0],
        lineWidth: 0.5,
        textColor: [0, 0, 0],
        overflow: 'linebreak',
        valign: 'middle'
      },
      headStyles: {
        fillColor: [255, 255, 255],
        textColor: [0, 0, 0],
        fontStyle: 'bold',
        lineWidth: 0.5
      },
      columnStyles: {
        0: {
          cellWidth: 20
        },
        1: {
          cellWidth: 'auto',
          minCellWidth: 100
        },
        2: {
          cellWidth: 45
        },
        3: {
          cellWidth: 35
        },
        4: {
          cellWidth: 45
        },
        5: {
          halign: 'right'
        },
        6: {
          halign: 'right'
        },
        7: {
          halign: 'right'
        },
        8: {
          halign: 'right'
        },
        9: {
          halign: 'right'
        },
        10: {
          halign: 'right'
        },
        11: {
          halign: 'right'
        },
        12: {
          halign: 'right'
        },
        13: {
          halign: 'center'
        },
        14: {
          halign: 'right'
        },
        15: {
          halign: 'right'
        }
      }
    });
    let currentY = doc.lastAutoTable.finalY + 20;
    const pageHeight = doc.internal.pageSize.height;
    let totalSchemeAmt = 0;
    let schemeLines = (invoiceData.invoice_lines || []).filter(l => l.tier_applied).map(l => {
      const amt = Number(l.scheme_amount || 0);
      totalSchemeAmt += amt;
      return [l.product_name, l.tier_applied, amt.toFixed(2)];
    });
    if (schemeLines.length === 0) {
      schemeLines = (invoiceData.order_lines || []).filter(l => l.tier_applied).map(l => {
        const amt = Number(l.scheme_amount || 0);
        totalSchemeAmt += amt;
        return [l.product_name, l.tier_applied, amt.toFixed(2)];
      });
    }
    if (schemeLines.length > 0) {
      schemeLines.push([{
        content: 'Total Scheme Discount',
        colSpan: 2,
        styles: {
          halign: 'right',
          fontStyle: 'bold'
        }
      }, {
        content: totalSchemeAmt.toFixed(2),
        styles: {
          halign: 'right',
          fontStyle: 'bold'
        }
      }]);
    }
    const estimatedFooterHeight = summaryData.length * 20 + schemeLines.length * 20 + 210;
    if (currentY + estimatedFooterHeight > pageHeight) {
      doc.addPage();
      drawMainHeader(doc.internal.getNumberOfPages(), doc.internal.getNumberOfPages());
      currentY = 157;
    }
    doc.autoTable({
      startY: currentY,
      margin: {
        left: margin
      },
      head: [["TAX SUMMARY", "PCS", "GROSS", "SCH", "DISC", "TAXABLE", "TAX", "NET"]],
      body: summaryData.map(row => [row.PARTICULARS, row.Pcs, row.Gross, row.Sch, row.Disc, row.Taxable, row.Tax, row.Net]),
      theme: 'grid',
      styles: {
        fontSize: 8.5,
        cellPadding: 2,
        lineColor: [0, 0, 0],
        lineWidth: 0.5,
        textColor: [0, 0, 0]
      },
      headStyles: {
        fillColor: [255, 255, 255],
        textColor: [0, 0, 0],
        fontStyle: 'bold'
      },
      bodyStyles: row => row.at(0).includes('Total') ? {
        fontStyle: 'bold',
        fillColor: [250, 250, 250]
      } : {}
    });
    if (schemeLines.length > 0) {
      doc.autoTable({
        startY: doc.lastAutoTable.finalY + 10,
        margin: {
          left: margin
        },
        head: [["PRODUCT NAME", "SCHEMES / TIER APPLIED", "SCHEME AMT"]],
        body: schemeLines,
        theme: 'grid',
        styles: {
          fontSize: 8,
          cellPadding: 3,
          lineColor: [0, 0, 0],
          lineWidth: 0.5,
          textColor: [0, 0, 0]
        },
        headStyles: {
          fillColor: [245, 245, 245],
          textColor: [0, 0, 0],
          fontStyle: 'bold'
        },
        columnStyles: {
          0: {
            cellWidth: 150
          },
          1: {
            cellWidth: 'auto'
          },
          2: {
            cellWidth: 70,
            halign: 'right'
          }
        }
      });
    }
    const wordsY = doc.lastAutoTable.finalY + 38;
    doc.setFontSize(10.5);
    doc.setFont("helvetica", "bold");
    doc.text(`Grand Total: ${Number(grandTotal).toFixed(2)}`, margin, wordsY - 14);
    doc.text("Total Amount (in words):", margin, wordsY);
    doc.setFont("helvetica", "normal");
    doc.text(toWords(Math.round(grandTotal)), margin + 140, wordsY);
    doc.setFontSize(8.5);
    doc.text("This is a computer generated document and does not require a physical signature.", margin, pageHeight - 170);
    const slipY = pageHeight - 160;
    doc.setDrawColor(0, 0, 0);
    doc.setLineDash([3, 3], 0);
    doc.line(margin, slipY, pageWidth - margin, slipY);
    doc.setLineDash([], 0);
    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    doc.text("RECEIPT ACKNOWLEDGEMENT", pageWidth / 2, slipY + 20, {
      align: "center"
    });
    const slipBoxY = slipY + 30;
    doc.rect(margin, slipBoxY, pageWidth - margin * 2, 100);
    doc.setFontSize(9);
    doc.text(`Invoice No: ${invoiceData.invoice_number}`, margin + 10, slipBoxY + 15);
    doc.text(`Date: ${moment(invoiceData.invoice_date).format("DD/MM/YYYY")}`, margin + 10, slipBoxY + 30);
    doc.text(`Customer: ${invoiceData.customer_name}`, margin + 10, slipBoxY + 45);
    doc.text(`Total Amount: ${Number(grandTotal).toFixed(2)}`, margin + 10, slipBoxY + 60);
    const bankInfoX = pageWidth / 2 + 5;
    doc.setFont("helvetica", "bold");
    doc.text("PAYMENT BANK DETAILS", bankInfoX, slipBoxY + 15);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.text(`Bank: ${bank.bank_name || "-"}`, bankInfoX, slipBoxY + 28);
    doc.text(`Acc No: ${bank.account_number || "-"}`, bankInfoX, slipBoxY + 38);
    doc.text(`IFSC: ${bank.ifsc_code || "-"}`, bankInfoX, slipBoxY + 48);
    doc.setFontSize(9);
    doc.text(`Receiver's Signature: __________________`, margin + 10, slipBoxY + 90);
    doc.text(`Authorized Signatory: __________________`, bankInfoX, slipBoxY + 90);
    doc.setFontSize(8);
    doc.setFont("helvetica", "bold");
    doc.text("Terms and Condition: ALL LEGAL DISPUTES ARE SUBJECT TO CALICUT JURIDICTION ONLY", margin, pageHeight - 15);
    const fileName = (invoiceData.invoice_number || "INV") + ".pdf";
    download(doc.output('dataurlstring'), fileName, "application/pdf");
    showAlert("Invoice Downloaded Successfully", "success");
  } catch (error) {
    showAlert("Invoice PDF Error: " + error.message, "error");
  }
}

